// Production server: static client assets from dist/client, everything else to TanStack Start.
// @ts-expect-error dist/ is generated by `bun run build`
import handler from './dist/server/server.js'

const CLIENT_DIR = new URL('./dist/client/', import.meta.url).pathname
const port = Number(process.env.PORT ?? 3000)

Bun.serve({
  port,
  async fetch(req) {
    const { pathname } = new URL(req.url)
    if (pathname !== '/' && !pathname.includes('..')) {
      const file = Bun.file(CLIENT_DIR + pathname.slice(1))
      if (await file.exists()) return new Response(file)
    }
    return handler.fetch(req)
  },
})

console.log(`Athar on http://localhost:${port}`)
